import {drawCharacter} from './world.js';
import {drawSprite} from './assets.js';
import {CITIES,INSTRUMENTS} from './core.js';
const reduced=typeof matchMedia!=='undefined'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
const PALETTES={Blues:['#111f32','#427b9d','#dbab70'],Rock:['#21161d','#c15d4d','#edc578'],Pop:['#29223b','#c381ac','#f2dab0'],Funk:['#202b26','#82ae75','#e1ac64'],Metal:['#171e2a','#7e91bc','#d9b4b1'],Latino:['#292320','#ce9865','#b8ce80'],Reggae:['#142d2c','#6aaa8e','#edcc85'],Jazz:['#111c32','#7789bd','#d8b27a']};
export function concertGeometry(W,H,lanes){const bottom=Math.min(360,W*.85),top=bottom*.45,hit=H*.83,horizon=H*.43;return {bottom,top,hit,horizon,lanes,cx:W/2};}
export function notePosition(g,beatsAhead){const q=Math.max(0,Math.min(1,1-beatsAhead/5));const depth=q*q;return {y:g.horizon+(g.hit-g.horizon)*depth,width:g.top+(g.bottom-g.top)*depth,depth};}
function box(ctx,x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke();}}
function ellipse(ctx,x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();}
function words(ctx,s,x,y,size=12,color='#fff0d0',align='center'){ctx.font=`${size}px Georgia,serif`;ctx.textAlign=align;ctx.fillStyle=color;ctx.fillText(s,x,y);}
function poly(ctx,pts,fill,stroke){ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1.5;ctx.stroke();}}
function musician(ctx,x,y,who,instrument,t,energy,player){const bounce=reduced?0:Math.sin(t*6+who)*energy*2;ctx.save();ctx.translate(x,y+bounce);if(player)ellipse(ctx,0,3,35,9,'#f8db9a35');ctx.scale(1.25,1.25);drawCharacter(ctx,0,0,{variant:who,facing:'south'});if(instrument==='drums')drawSprite(ctx,'band',3,2,0,13,78,51);else{ctx.save();ctx.translate(4,-12);ctx.rotate((instrument==='guitar'?-.55:-.35)+(reduced?0:Math.sin(t*7+who)*.04));drawSprite(ctx,'band',3,instrument==='guitar'?0:1,0,16,47,52);ctx.restore();}ctx.restore();}
export function drawConcert(ctx,{song:s,time:t,W,H,instrument}){const inst=INSTRUMENTS[instrument],city=CITIES[s.city],g=concertGeometry(W,H,inst.lanes),palette=PALETTES[city.genre]||['#182a2a','#779b88','#e5bd7f'],[dark,accent,gold]=palette,energy=Math.min(1,.25+s.combo/30),beatPulse=reduced?.3:Math.pow(1-((Math.max(0,t-2)/s.beat)%1),3),wide=W>650;
 ctx.save();const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,dark);sky.addColorStop(.6,'#14252b');sky.addColorStop(1,'#071218');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
 // Warm theatre curtains, truss and beams: motion is decorative, never applied to notes.
 for(let side=0;side<2;side++){const x=side?W-40:0;const curtain=ctx.createLinearGradient(x,0,x+40,0);curtain.addColorStop(0,'#141c24');curtain.addColorStop(.5,accent+'77');curtain.addColorStop(1,'#141c24');ctx.fillStyle=curtain;ctx.fillRect(x,0,40,H*.45);}
 for(let i=0;i<5;i++){const x=W*(.12+i*.19),sway=reduced?0:Math.sin(t*.5+i)*W*.08;poly(ctx,[[x-6,53],[x+6,53],[x+sway+W*.13,H*.43],[x+sway-W*.13,H*.43]],accent+(i%2?'12':'1b'));ellipse(ctx,x,53,7,5,gold);}
 box(ctx,W*.08,66,W*.84,4,2,'#8d988077');for(let i=0;i<11;i++)ellipse(ctx,W*(.1+i*.08),68,2,2,gold);
 const stageY=H*.36;box(ctx,W*.07,stageY-9,W*.86,H*.1,8,'#6d5544');for(let i=0;i<6;i++)box(ctx,W*.08,stageY+i*9,W*.84,1,0,'#ddbf8130');box(ctx,W*.07,stageY+H*.08,W*.86,9,3,'#b29465');
 const label=s.kind==='tutorial'?'IL GARAGE · LA PRIMA PROVA':s.kind==='rival'?'ALTA TENSIONE · LA SFIDA':s.kind==='final'?'FESTIVAL DELLE OTTO STRADE':s.kind==='boat'?'CONCERTO SUL MARE':city.name.toUpperCase()+' · LIVE';words(ctx,label,W/2,85,W<400?10:14,gold);words(ctx,inst.name.toUpperCase()+' · '+(city.genre==='Casa'?'LA NOSTRA BAND':city.genre.toUpperCase()),W/2,103,10,'#d3d7c0');
 const band=Object.keys(INSTRUMENTS).filter(k=>k!==instrument);musician(ctx,W*.5,stageY-18,0,instrument,t,energy,true);musician(ctx,W*.28,stageY-22,1,band[0],t,energy,false);musician(ctx,W*.72,stageY-22,2,band[1],t,energy,false);
 for(const x of [W*.12,W*.88]){drawSprite(ctx,'band',3,3,x,stageY+10,46,55);ellipse(ctx,x,stageY+6,7,3,accent);}
 // Audience around the runway, with individual silhouettes and arms.
 for(let row=0;row<3;row++)for(let side=0;side<2;side++)for(let i=0;i<(wide?7:3);i++){const x=side?W-(18+i*(wide?25:15)):18+i*(wide?25:15),y=H*.65+row*H*.095,bob=reduced?0:Math.sin(t*3+i+row)*energy*3;if(Math.abs(x-W/2)<g.bottom/2+18)continue;ellipse(ctx,x,y+bob,7+row,9+row,'#0b171f');box(ctx,x-12-row,y+7+bob,24+row*2,33,10,row%2?'#172631':'#1e3036');if(s.combo>=10){ctx.strokeStyle=accent+'88';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x-8,y+15);ctx.lineTo(x-18,y-10+bob);ctx.moveTo(x+8,y+15);ctx.lineTo(x+18,y-14-bob);ctx.stroke();}}
 // Perspective highway with a fixed, high contrast timing line.
 const topL=g.cx-g.top/2,botL=g.cx-g.bottom/2;poly(ctx,[[topL-7,g.horizon],[topL+g.top+7,g.horizon],[botL+g.bottom+12,g.hit+30],[botL-12,g.hit+30]],'#e0c59b24');poly(ctx,[[topL,g.horizon],[topL+g.top,g.horizon],[botL+g.bottom,g.hit+25],[botL,g.hit+25]],'#09141fee','#ccb38b77');
 ctx.save();ctx.beginPath();ctx.moveTo(topL,g.horizon);ctx.lineTo(topL+g.top,g.horizon);ctx.lineTo(botL+g.bottom,g.hit+24);ctx.lineTo(botL,g.hit+24);ctx.closePath();ctx.clip();for(let l=0;l<inst.lanes;l++){const col=inst.colors[l];poly(ctx,[[topL+l*g.top/inst.lanes,g.horizon],[topL+(l+1)*g.top/inst.lanes,g.horizon],[botL+(l+1)*g.bottom/inst.lanes,g.hit+25],[botL+l*g.bottom/inst.lanes,g.hit+25]],s.pressed.has(l)?col+'35':l%2?'#21334255':'#15253555');}
 for(let i=Math.floor((t-2)/s.beat);i<(t-2)/s.beat+6;i++){const p=notePosition(g,(2+i*s.beat-t)/s.beat);if(2+i*s.beat<t)continue;ctx.strokeStyle=i%4===0?'#e6d7b34d':'#829bac24';ctx.beginPath();ctx.moveTo(g.cx-p.width/2,p.y);ctx.lineTo(g.cx+p.width/2,p.y);ctx.stroke();}
 for(const n of s.notes){if(n.status==='hit'||n.status==='miss')continue;const ahead=(n.t-t)/s.beat;if(ahead>5||ahead<-.5)continue;const p=notePosition(g,ahead),laneW=p.width/inst.lanes,x=g.cx-p.width/2+(n.lane+.5)*laneW,col=inst.colors[n.lane],r=Math.max(4,laneW*.29);if(n.duration){const tail=notePosition(g,(n.t+n.duration-t)/s.beat),tx=g.cx-tail.width/2+(n.lane+.5)*tail.width/inst.lanes;poly(ctx,[[x-r*.3,p.y],[x+r*.3,p.y],[tx+r*.18,tail.y],[tx-r*.18,tail.y]],col+'99');}if(n.status!=='holding'){ellipse(ctx,x,p.y+3,r,r*.48,'#0008');ellipse(ctx,x,p.y,r,r*.48,col);ellipse(ctx,x,p.y-2,r*.68,r*.22,'#fff2ceaa');words(ctx,String(n.lane+1),x,p.y+3,Math.max(9,12*p.depth),'#14232a');}}
 ctx.restore();
 ctx.strokeStyle=gold;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(botL-7,g.hit);ctx.lineTo(botL+g.bottom+7,g.hit);ctx.stroke();for(let l=0;l<inst.lanes;l++){const x=botL+(l+.5)*g.bottom/inst.lanes,r=g.bottom/inst.lanes*.32,col=inst.colors[l];ellipse(ctx,x,g.hit,r+3,13,'#101c24');ctx.strokeStyle=col;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,g.hit,r,10,0,0,Math.PI*2);ctx.stroke();if(s.pressed.has(l))ellipse(ctx,x,g.hit,r*.75,7,col);words(ctx,inst.labels[l],x,g.hit+29,13,col);}
 // Successful hits use bounded rings and particles; mistakes never shake the highway.
 for(const fx of s.hitEffects||[]){const age=t-fx.t;if(age<0||age>.45)continue;const x=botL+(fx.lane+.5)*g.bottom/inst.lanes,life=1-age/.45,col=inst.colors[fx.lane];ctx.globalAlpha=life;ellipse(ctx,x,g.hit,12+age*65,5+age*28,col+'66');if(!reduced)for(let i=0;i<5;i++){const a=i*Math.PI*.4;ellipse(ctx,x+Math.cos(a)*age*95,g.hit-10-Math.sin(a)*age*95,2.5,2.5,gold);}ctx.globalAlpha=1;}
 const sideX=wide?W*.17:W-32,sideY=wide?H*.48:H*.54;if(s.combo>1)words(ctx,s.combo+' ×',sideX,sideY,wide?40:22,gold);else if(wide)words(ctx,'É IL TUO PALCO',sideX,sideY,13,gold);if(wide){words(ctx,'SERIE MIGLIORE · '+s.maxCombo,sideX,sideY+26,11,'#bccbc7');words(ctx,s.combo>=20?'IL PUBBLICO È CON VOI':s.combo>=10?'LA BAND TROVA IL GROOVE':'ASCOLTATEVI',W*.83,H*.48,12,gold);}
 if(t<2){box(ctx,W/2-52,H*.52-45,104,94,18,'#12232ee8',gold);words(ctx,String(Math.max(1,4-Math.floor(Math.max(0,t)/.5))),W/2,H*.52+17,64,gold);}else if(t<s.feedbackUntil){box(ctx,W/2-87,g.horizon-25,174,28,10,'#101e2aee');words(ctx,s.feedback,W/2,g.horizon-6,12,s.feedback==='CERCA IL TEMPO'?'#e5b09c':gold);}
 const progress=Math.max(0,Math.min(1,t/s.duration));box(ctx,16,H-8,W-32,3,1,'#52687644');if(progress)box(ctx,16,H-8,(W-32)*progress,3,1,gold);ctx.restore();}
